import subprocess
def t(text, label=''):
    open('y.tex','w').write(text)
    r = subprocess.run(['/workspace/executable', '--print', 'y.tex'], capture_output=True, text=True)
    print(f"--- {label} rc={r.returncode}")
    for l in r.stdout.split('
')[1:-2]:
        print(f"    [{len(l)}] {l}")
A = 'a'*30
base = "start {} end more words here to make the line long enough to need wrapping yes"
t(f'\begin{{document}}
{base.format(A)}
\end{{document}}
','plain A30')
t(f'\begin{{document}}
{base.format("x"*30)}
\end{{document}}
','plain x30')
t(f'\begin{{document}}
{base.format("\foo{}")}
\end{{document}}
','cmd empty')
t(f'\begin{{document}}
{base.format("\foo{bar}")}
\end{{document}}
','cmd bar')
t(f'\begin{{document}}
{base.format("a"*29)}
\end{{document}}
','A29')
EOF

