{"command": "cd /tmp/t && python3 - <<'EOF'
import subprocess
def t(text):
    open('y.tex','w').write(text)
    r = subprocess.run(['/workspace/executable', '--print', 'y.tex'], capture_output=True, text=True)
    return r.stdout
def words_for(c):
    if c % 2 == 1:
        k=(c+1)//2; w=['a']*k
    else:
        k=(c-2)//2; w=['a']*k+['aa']
    return ' '.join(w)
for ind in (0,1,2,3):
    pad = '  '*ind
    res=[]
    for c in range(60,90,2):
        line = words_for(c)
        assert len(line)==c,(len(line),c)
        out = t('\\begin{document}\n\\begin{itemize}\n'+pad+line+'\n\\end{itemize}\n\\end{document}\n')
        body=[l for l in out.split('\n') if l.strip() and not l.strip().startswith('\\end') and not l.strip().startswith('\\begin')]
        lens=[len(l.strip()) for l in body]
        res.append((ind*2+c, lens))
    for x in res: print(f"  indent{ind*2} total={x[0]} -> {x[1]}")
EOF"}

