import subprocess
def t(text, args=('--print',)):
    open('y.tex','w').write(text)
    r = subprocess.run(['/workspace/executable', *args, 'y.tex'], capture_output=True, text=True)
    return r.stdout
def words_for(c):
    if c % 2 == 1:
        k=(c+1)//2; w=['a']*k
    else:
        k=(c-2)//2; w=['a']*k+['aa']
    return ' '.join(w)
for L in (80, 100, 60, 90):
    print(f"=== wraplen {L}")
    for c in range(66, 96, 2):
        line = words_for(c)
        out = t('\\begin{document}\n'+line+'\n\\end{document}\n', ('--print','-l',str(L)))
        body=[l for l in out.split('\n')[1:-2]]
        print(f"  c={c} -> {[(len(l)) for l in body]}")
EOF"}

