//! Logging utilities.
use std::io::Write;

/// Verbosity levels, ordered from most to least verbose.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Verbosity {
    Trace,
    Info,
    Warn,
    Error,
    Quiet,
}

impl Verbosity {
    /// Parse a verbosity string, returning `None` if invalid.
    pub fn parse(s: &str) -> Option<Verbosity> {
        match s {
            "trace" => Some(Verbosity::Trace),
            "info" => Some(Verbosity::Info),
            "warn" => Some(Verbosity::Warn),
            "error" => Some(Verbosity::Error),
            "quiet" => Some(Verbosity::Quiet),
            _ => None,
        }
    }
}

fn level_text(v: Verbosity) -> &'static str {
    match v {
        Verbosity::Trace => "TRACE",
        Verbosity::Info => "INFO",
        Verbosity::Warn => "WARN",
        Verbosity::Error => "ERROR",
        Verbosity::Quiet => "",
    }
}

fn color(v: Verbosity) -> &'static str {
    match v {
        Verbosity::Trace => "34",
        Verbosity::Info => "32",
        Verbosity::Warn => "33",
        Verbosity::Error => "31",
        Verbosity::Quiet => "",
    }
}

/// Write a log message to stderr.
pub fn log(verbosity: Verbosity, threshold: Verbosity, file: &str, msg: &str) {
    if verbosity > threshold {
        return;
    }
    let text = level_text(verbosity);
    if text.is_empty() {
        return;
    }
    let stderr = std::io::stderr();
    let mut handle = stderr.lock();
    if is_terminal() {
        let _ = writeln!(
            handle,
            "\u{1b}[1;{}m{}:\u{1b}[0m tex-fmt {}: {} ",
            color(verbosity),
            text,
            file,
            msg
        );
    } else {
        let _ = writeln!(handle, "{}: tex-fmt {}: {} ", text, file, msg);
    }
}
RUSTEOF
echo ok"}

