//! Tokenizer and formatter for LaTeX source files.
use crate::config::Config;
use crate::log;

/// Kind of a token, determined by the first characters of the token.
#[derive(Clone, Debug, PartialEq)]
pub enum Kind {
    /// Normal text.
    Text,
    /// `\begin{env}` with the environment name.
    Begin(String),
    /// `\end{env}` with the environment name.
    End(String),
    /// `\item` or `\item[...]`
    Item,
}

/// A single token of the document.
#[derive(Clone, Debug)]
pub struct Token {
    /// Text of the token, without any surrounding whitespace.
    pub text: String,
    /// Whitespace between the previous token and this one.
    pub sep: String,
    /// Kind of token.
    pub kind: Kind,
    /// True if token is part of a comment.
    pub comment: bool,
    /// True if a line break must be inserted before this token.
    pub split: bool,
    /// Effect of token on the indentation level.
    pub delta: i32,
    /// Parts used to compute indentation: positive values open, negative close.
    pub parts: Vec<i32>,
}

impl Token {
    fn new(text: String, sep: String) -> Token {
        Token {
            text,
            sep,
            kind: Kind::Text,
            comment: false,
            split: false,
            delta: 0,
            parts: vec![],
        }
    }
    /// True if token starts with an `\item`.
    pub fn is_item(&self) -> bool {
        matches!(self.kind, Kind::Item)
    }
    /// Number of characters that would be added when appending this token.
    pub fn width(&self) -> usize {
        self.text.chars().count() + self.sep.chars().count()
    }
}

/// Indentation contribution of a single environment.
fn env_delta(env: &str, cfg: &Config) -> i32 {
    if cfg.no_indent_envs.iter().any(|e| e == env) {
        0
    } else if cfg.lists.iter().any(|e| e == env) {
        2
    } else {
        1
    }
}

/// Expand tabs in a string to `tabsize` spaces.
fn expand_tabs(s: &str, tabsize: usize) -> String {
    if !s.contains('\t') {
        return s.to_string();
    }
    let n = tabsize.max(1);
    s.replace('\t', &" ".repeat(n))
}

/// Convert a source line into a list of tokens.
pub fn tokenize(line: &str, cfg: &Config) -> Vec<Token> {
    let line = expand_tabs(line, cfg.tabsize);
    let trimmed = line.trim_matches(' ');
    if trimmed.is_empty() {
        return vec![];
    }
    let chars: Vec<char> = trimmed.chars().collect();
    let mut tokens: Vec<Token> = vec![];
    let mut i = 0;
    let mut sep = String::new();
    while i < chars.len() {
        if chars[i] == '%' {
            // Comment: take '%' plus any directly following text as one token,
            // then treat the remainder of the line as comment body.
            let start = i;
            i += 1;
            while i < chars.len() && chars[i] != ' ' {
                i += 1;
            }
            let text: String = chars[start..i].iter().collect();
            let mut tok = Token::new(text, sep.clone());
            tok.comment = true;
            tok.parts.push(0);
            tokens.push(tok);
            sep = String::new();
            continue;
        }
        // Find the end of the next "word", splitting at special commands.
        let start = i;
        let mut end = chars.len();
        let mut j = i;
        while j < chars.len() {
            if chars[j] == '%' {
                end = j;
                break;
            }
            if chars[j] == '\\' {
                // Check for special commands.
                if let Some((len, kind)) = special_command(&chars, j) {
                    if j > start {
                        end = j;
                        break;
                    }
                    // Token starts with special command; find its end.
                    let stop = match kind {
                        SpecialKind::Begin | SpecialKind::End => env_end(&chars, j + len),
                        SpecialKind::Item => j + len,
                    };
                    end = stop;
                    break;
                }
                // Escaped character: skip it.
                j += 2;
                continue;
            }
            j += 1;
        }
        if end == chars.len() && j >= chars.len() {
            end = chars.len();
        }
        let text: String = chars[start..end.min(chars.len())].iter().collect();
        let mut tok = Token::new(text, sep.clone());
        classify(&mut tok, cfg);
        tokens.push(tok);
        sep = String::new();
        i = end;
        // Skip whitespace.
        let mut k = i;
        while k < chars.len() && chars[k] == ' ' {
            k += 1;
        }
        if k > i {
            sep = " ".repeat(k - i);
        }
        i = k;
    }
    // Store the separator belonging to each token.
    for k in (1..tokens.len()).rev() {
        let s = tokens[k].sep.clone();
        tokens[k - 1].sep = s;
        tokens[k].sep = String::new();
    }
    if !tokens.is_empty() {
        let s = tokens.last().unwrap().sep.clone();
        tokens.last_mut().unwrap().sep = s;
    }
    tokens
}
RUSTEOF
echo ok"}

