fn special_name(chars: &[char], pos: usize) -> Option<&'static str> {
    let rest: String = chars[pos..].iter().collect();
    for name in ["begin", "end", "item"] {
        let cmd = format!("\\{}", name);
        if rest.starts_with(&cmd) {
            let after = pos + cmd.chars().count();
            if after < chars.len() {
                let c = chars[after];
                match name {
                    "item" => {
                        if !c.is_alphabetic() {
                            return Some("item");
                        }
                    }
                    _ => {
                        if c == '{' {
                            return Some(name);
                        }
                    }
