    let mut depth = 0usize;
    let mut j = brace + 1;
    while j < chars.len() {
        match chars[j] {
            '{' => depth += 1,
            '}' => {
                if depth == 0 {
                    let name: String = chars[brace + 1..j].iter().collect();
                    return (Some(name), j + 1);
                }
                depth -= 1;
            }
            _ => {}
        }
        j += 1;
    }
    (None, chars.len())
}

