//! Tokenizer and formatter for LaTeX source files.
use crate::config::Config;
use crate::log::Verbosity;

/// Kind of a token, determined by the first characters of the token.
#[derive(Clone, Debug, PartialEq)]
pub enum Kind {
    /// Normal text.
    Text,
    /// `\begin{env}` with the environment name.
    Begin(String),
    /// `\end{env}` with the environment name.
    End(String),
    /// `\item` or `\item[...]`
    Item,
}

/// A single token of the document.
#[derive(Clone, Debug)]
pub struct Token {
    /// Text of the token, without any surrounding whitespace.
    pub text: String,
    /// Whitespace between the previous token and this one.
    pub sep: String,
    /// Kind of token.
    pub kind: Kind,
    /// True if token is part of a comment.
    pub comment: bool,
    /// True if a line break must be inserted before this token.
    pub split: bool,
    /// Effect of token on the indentation level.
    pub delta: i32,
    /// Sequence of opening (positive) and closing (negative) contributions,
    /// used to determine indentation of the following line.
    pub parts: Vec<i32>,
}

impl Token {
    fn new(text: String, sep: String) -> Token {
        Token {
            text,
            sep,
            kind: Kind::Text,
            comment: false,
            split: false,
            delta: 0,
            parts: vec![],
        }
    }
    /// True if token starts with an `\item`.
    pub fn is_item(&self) -> bool {
        matches!(self.kind, Kind::Item)
    }
    /// Content of the line made up of this token only.
    pub fn len(&self) -> usize {
        self.text.chars().count()
    }
}

/// Indentation contribution of a single environment.
fn env_delta(env: &str, cfg: &Config) -> i32 {
    if cfg.no_indent_envs.iter().any(|e| e == env) {
        0
    } else if cfg.lists.iter().any(|e| e == env) {
        2
    } else {
        1
    }
}

/// True if environment name is a verbatim environment.
fn is_verbatim(env: &str, cfg: &Config) -> bool {
    cfg.verbatims.iter().any(|e| e == env)
}

/// Expand tabs in a string to `tabsize` spaces.
fn expand_tabs(s: &str, tabsize: usize) -> String {
    if !s.contains('\t') {
        return s.to_string();
    }
    let n = if tabsize == 0 { 1 } else { tabsize };
    s.replace('\t', &" ".repeat(n))
}

/// Try to match a special command (`\begin{`, `\end{`, `\item`) at `pos`.
/// Returns the number of characters of the command name (without brace).
fn special_name(chars: &[char], pos: usize) -> Option<&'static str> {
    let rest: String = chars[pos..].iter().collect();
    for name in ["begin", "end", "item"] {
        let cmd = format!("\\{}", name);
        if rest.starts_with(&cmd) {
            let after = pos + cmd.chars().count();
            if after < chars.len() {
                let c = chars[after];
                match name {
                    "item" => {
                        if !c.is_alphabetic() {
                            return Some("item");
                        }
                    }
                    _ => {
                        if c == '{' {
                            return Some(name);
                        }
                    }
                }
            } else if name == "item" {
                return Some("item");
            }
        }
    }
    None
}

/// Parse environment name beginning at the brace at `pos`.
/// Returns the name and the index just after the closing brace.
/// If no closing brace is found, the name is the rest of the line and
/// `None` is returned together with the end of the line.
fn parse_env(chars: &[char], brace: usize) -> (Option<String>, usize) {
    let mut depth = 0usize;
    let mut j = brace + 1;
    while j < chars.len() {
        match chars[j] {
            '{' => depth += 1,
            '}' => {
                if depth == 0 {
                    let name: String = chars[brace + 1..j].iter().collect();
                    return (Some(name), j + 1);
                }
                depth -= 1;
            }
            _ => {}
        }
        j += 1;
    }
    (None, chars.len())
}

/// Scan the remaining characters of a line from `start`, producing tokens.
fn scan(chars: &[char], start: usize, cfg: &Config, comment: bool) -> (usize, Token) {
    let mut pos = start;
    if !comment && chars[start] == '%' {
        // Comment token: '%' and directly following characters.
        let mut end = start + 1;
        while end < chars.len() && chars[end] != ' ' {
            end += 1;
        }
        let mut tok = Token::new(chars[start..end].iter().collect(), String::new());
        tok.comment = true;
        return (end, tok);
    }
    let mut delta = 0i32;
    let mut parts: Vec<i32> = vec![];
    let mut kind = Kind::Text;
    let mut item = false;
    while pos < chars.len() {
        let c = chars[pos];
        if !comment && c == '%' {
            break;
        }
        if c == '\\' && pos + 1 < chars.len() && chars[pos + 1].is_alphabetic() {
            if let Some(name) = special_name(chars, pos) {
                let cmd_len = name.chars().count() + 1;
                match name {
                    "begin" | "end" => {
                        let brace = pos + cmd_len;
                        let (env, after) = parse_env(chars, brace);
                        if let Some(env) = env {
                            let d = env_delta(&env, cfg);
                            if name == "begin" {
                                delta += d;
                                kind = Kind::Begin(env);
                            } else {
                                delta -= d;
                                parts.push(-d);
                                kind = Kind::End(env);
                            }
                            pos = after;
                        } else {
                            if name == "begin" {
                                delta += 1;
                            } else {
