//! Configuration of formatter.
use std::fs;
use std::path::{Path, PathBuf};

use crate::log::Verbosity;

/// Character used for indentation.
#[derive(Clone, Debug, PartialEq, Eq, Copy)]
pub enum TabChar {
    Space,
    Tab,
}

impl TabChar {
    fn parse(s: &str) -> Option<TabChar> {
        match s {
            "space" => Some(TabChar::Space),
            "tab" => Some(TabChar::Tab),
            _ => None,
        }
    }
    pub fn text(&self) -> &'static str {
        match self {
            TabChar::Space => "space",
            TabChar::Tab => "tab",
        }
    }
    pub fn is_tab(&self) -> bool {
        matches!(self, TabChar::Tab)
    }
}

/// All settings used by the formatter.
#[derive(Clone, Debug, PartialEq)]
pub struct Config {
    pub check: bool,
    pub print: bool,
    pub fail_on_change: bool,
    pub wrap: bool,
    pub wraplen: usize,
    pub wrapmin: usize,
    pub tabsize: usize,
    pub tabchar: TabChar,
    pub stdin: bool,
    pub config: Option<String>,
    pub verbosity: Verbosity,
    pub lists: Vec<String>,
    pub verbatims: Vec<String>,
    pub no_indent_envs: Vec<String>,
    pub wrap_chars: Vec<char>,
    pub files: Vec<String>,
}

impl Default for Config {
    fn default() -> Config {
        Config {
            check: false,
            print: false,
            fail_on_change: false,
            wrap: true,
            wraplen: 80,
            wrapmin: 70,
            tabsize: 2,
            tabchar: TabChar::Space,
            stdin: false,
            config: None,
            verbosity: Verbosity::Warn,
            lists: vec![
                "itemize".into(),
                "enumerate".into(),
                "description".into(),
                "inlineroman".into(),
                "inventory".into(),
            ],
            verbatims: vec![
                "verbatim".into(),
                "Verbatim".into(),
                "lstlisting".into(),
                "minted".into(),
                "comment".into(),
            ],
            no_indent_envs: vec!["document".into()],
            wrap_chars: vec![],
            files: vec![],
        }
    }
}

impl Config {
    /// Read configuration from a TOML file, applying it to `self`.
    pub fn read_toml(&mut self, path: &str) {
        let text = fs::read_to_string(path).unwrap();
        let value = text.parse::<toml::Table>().unwrap();
        for (key, val) in value.iter() {
            match key {
                "check" => self.check = val.as_bool().unwrap_or(self.check),
                "print" => self.print = val.as_bool().unwrap_or(self.print),
                "fail-on-change" => self.fail_on_change = val.as_bool().unwrap_or(self.fail_on_change),
                "wrap" => self.wrap = val.as_bool().unwrap_or(self.wrap),
                "wraplen" => {
                    if let Some(n) = val.as_integer() {
                        self.wraplen = n.max(0) as usize;
                    }
                }
                "wrapmin" => {
                    if let Some(n) = val.as_integer() {
                        self.wrapmin = n.max(0) as usize;
                    }
                }
                "tabsize" => {
                    if let Some(n) = val.as_integer() {
                        self.tabsize = n.max(0) as usize;
                    }
                }
                "tabchar" => {
                    if let Some(s) = val.as_str() {
                        if let Some(c) = TabChar::parse(s) {
                            self.tabchar = c;
                        }
                    }
                }
                "stdin" => self.stdin = val.as_bool().unwrap_or(self.stdin),
                "verbosity" => {
                    if let Some(s) = val.as_str() {
                        if let Some(v) = Verbosity::parse(s) {
                            self.verbosity = v;
                        }
                    }
                }
                "lists" => {
                    if let Some(arr) = val.as_array() {
                        let mut v = vec![];
                        for item in arr.iter() {
                            if let Some(s) = item.as_str() {
                                v.push(s.to_string());
                            }
                        }
                        self.lists = v;
                    }
                }
                "verbatims" => {
                    if let Some(arr) = val.as_array() {
                        let mut v = vec![];
                        for item in arr.iter() {
                            if let Some(s) = item.as_str() {
                                v.push(s.to_string());
                            }
                        }
                        self.verbatims = v;
                    }
                }
                "no-indent-envs" => {
                    if let Some(arr) = val.as_array() {
                        let mut v = vec![];
                        for item in arr.iter() {
                            if let Some(s) = item.as_str() {
                                v.push(s.to_string());
                            }
                        }
                        self.no_indent_envs = v;
                    }
                }
                "wrap-chars" => {
                    if let Some(arr) = val.as_array() {
                        let mut v = vec![];
                        for item in arr.iter() {
                            if let Some(s) = item.as_str() {
                                let mut it = s.chars();
                                let c = it.next().unwrap();
                                v.push(c);
                            }
                        }
                        self.wrap_chars = v;
                    }
                }
                _ => {}
            }
        }
    }

    /// Set `wrapmin` based on `wraplen` if not set explicitly.
    pub fn update_wrapmin(&mut self) {
        if self.wraplen >= 50 {
            self.wrapmin = self.wraplen - 10;
        } else {
            self.wrapmin = self.wraplen;
        }
    }

    /// String representation of configuration for `--args`.
    pub fn args_string(&self) -> String {
        let mut s = String::new();
        s.push_str("tex-fmt\n");
        let mut add = |name: &str, value: &str| {
            s.push_str(&format!("  {:23} {}\n", format!("{}:", name), value));
        };
        add("check", &self.check.to_string());
        add("print", &self.print.to_string());
        add("fail-on-change", &self.fail_on_change.to_string());
        add("wrap", &self.wrap.to_string());
        add("wraplen", &self.wraplen.to_string());
        add("wrapmin", &self.wrapmin.to_string());
        add("tabsize", &self.tabsize.to_string());
        add("tabchar", self.tabchar.text());
        add("stdin", &self.stdin.to_string());
        match &self.config {
            Some(p) => add("config", p),
            None => add("config", "None"),
        }
        add("verbosity", verbosity_string(self.verbosity));
        let list_str = |items: &Vec<String>| -> String {
            if items.is_empty() {
                " ".to_string()
            } else {
                items
                    .iter()
                    .map(|i| i.clone())
                    .collect::<Vec<_>>()
                    .join(&format!("\n{}", " ".repeat(27)))
            }
        };
        s.push_str(&format!("  {:23} {}\n", "lists:", list_str(&self.lists)));
        s.push_str(&format!(
            "  {:23} {}\n",
            "verbatims:",
            list_str(&self.verbatims)
        ));
        s.push_str(&format!(
            "  {:23} {}\n",
            "no-indent-envs:",
            list_str(&self.no_indent_envs)
        ));
        let wc: Vec<String> = self.wrap_chars.iter().map(|c| c.to_string()).collect();
        s.push_str(&format!(
            "  {:23} {}\n",
            "wrap-chars:",
            if wc.is_empty() {
                " ".to_string()
            } else {
                wc.join(&format!("\n{}", " ".repeat(27)))
            }
        ));
        if !self.files.is_empty() {
            s.push_str(&format!("  {:23} {}\n", "files:", self.files[0]));
            for f in &self.files[1..] {
                s.push_str(&format!("{}{}\n", " ".repeat(27), f));
            }
        }
        s
    }
}

pub fn verbosity_string(v: Verbosity) -> &'static str {
    match v {
        Verbosity::Trace => "trace",
        Verbosity::Info => "info",
        Verbosity::Warn => "warn",
        Verbosity::Error => "error",
        Verbosity::Quiet => "quiet",
    }
}

/// Find a configuration file, searching from the current directory upwards.
pub fn find_config() -> Option<PathBuf> {
    let cwd = std::env::current_dir().ok()?;
    let mut dir: Option<&Path> = Some(cwd.as_path());
    while let Some(d) = dir {
        let candidate = d.join("tex-fmt.toml");
        if candidate.is_file() {
            return Some(candidate);
        }
        // Stop at git repository root.
