//! Formatting of LaTeX source files.
use std::cmp;

use crate::config::Config;
use crate::log::{self, Verbosity};
use crate::tex::{tokenize, Kind, Token};

/// Lines to be formatted.
pub struct Formatter<'a> {
    cfg: &'a Config,
    file: String,
    /// Output lines.
    out: Vec<String>,
    /// Current indentation level.
    level: i32,
    /// Number of output lines written so far.
    out_num: usize,
    /// Number of input line being processed.
    in_num: usize,
    /// Index of first output line with negative indentation.
    first_negative: Option<usize>,
    /// Index of last output line with zero indentation.
    last_zero: Option<usize>,
}

impl<'a> Formatter<'a> {
    pub fn new(cfg: &'a Config, file: &str) -> Formatter<'a> {
        Formatter {
            cfg,
            file: file.to_string(),
            out: vec![],
            level: 0,
            out_num: 0,
            in_num: 0,
            first_negative: None,
            last_zero: None,
        }
    }

    fn log(&self, verbosity: Verbosity, msg: &str) {
        log::log(verbosity, self.cfg.verbosity, &self.file, msg);
    }

    fn line_msg(&self, verbosity: Verbosity, msg: &str, content: &str) {
        self.log(
            verbosity,
            &format!(
                "Line {} ({}). {} {}",
                self.out_num + 1,
                self.in_num,
                msg,
                content
            ),
        );
    }

    /// Compute indentation level of a line from its leading tokens.
    fn dedent(tokens: &[Token]) -> i32 {
        let mut depth = 0i32;
        let mut dedent = 0i32;
        for (i, tok) in tokens.iter().enumerate() {
            if i == 0 && tok.is_item() {
                dedent += 1;
            }
            for &p in &tok.parts {
                if p > 0 {
                    depth += p;
                } else if depth >= -p {
                    depth += p;
                } else {
                    dedent += -p - depth;
                    depth = 0;
                }
            }
        }
        dedent
    }

    /// Total indentation change of a list of tokens.
    fn delta(tokens: &[Token]) -> i32 {
        tokens.iter().map(|t| t.delta).sum()
    }

    /// Concatenate tokens into a string, keeping separators.
    fn content(tokens: &[Token]) -> String {
        let mut s = String::new();
        for t in tokens {
            s.push_str(&t.sep);
            s.push_str(&t.text);
        }
        s
    }

    /// Length of a string in characters.
    fn width(s: &str) -> usize {
        s.chars().count()
    }

    /// Indentation string for a given level.
    fn indent_str(&self, level: i32) -> String {
        let n = cmp::max(level, 0) as usize * self.cfg.tabsize;
        if self.cfg.tabchar.is_tab() {
            "\t".repeat(n)
        } else {
            " ".repeat(n)
        }
    }

    /// Width of indentation at a given level, as used for wrapping.
    fn indent_width(&self, level: i32) -> usize {
        cmp::max(level, 0) as usize * self.cfg.tabsize
    }

    /// Split tokens at characters after which lines may be wrapped.
    fn split_wrap_chars(&self, tokens: &[Token]) -> Vec<Token> {
        if self.cfg.wrap_chars.is_empty() {
            return tokens.to_vec();
        }
        let mut out = vec![];
        for tok in tokens {
            let mut pieces = vec![];
            let mut cur = String::new();
            for c in tok.text.chars() {
                cur.push(c);
                if self.cfg.wrap_chars.contains(&c) {
                    pieces.push(cur);
                    cur = String::new();
                }
            }
            if !cur.is_empty() {
                pieces.push(cur);
            }
            if pieces.len() <= 1 {
                out.push(tok.clone());
                continue;
            }
            for (i, p) in pieces.iter().enumerate() {
                let mut t = tok.clone();
                t.text = p.clone();
                if i > 0 {
                    t.sep = String::new();
                }
                out.push(t);
            }
        }
        out
    }

    /// Process one source line, appending output lines.
    fn process_line(&mut self, raw: &str) {
        let tokens = tokenize(raw, self.cfg);
        let content = Self::content(&tokens);
        let dedent = Self::dedent(&tokens);
        let visual = self.level - dedent;
        let actual = self.level + Self::delta(&tokens);
        self.trace_indent(&content, actual, visual);
        if visual < 0 {
            self.line_msg(Verbosity::Warn, "Indent is negative", &content);
        }
        if self.wrap_needed(&content, visual) {
            self.log(
                Verbosity::Trace,
                &format!(
                    "Line {} ({}). Wrapping long line. {}",
                    self.out_num + 1,
                    self.in_num,
                    content
                ),
            );
            let wrapped = self.wrap_tokens(&tokens, visual, &content);
            if wrapped.is_none() {
