//! Formatting of LaTeX source files.
use std::cmp;

use crate::config::Config;
use crate::log::{self, Verbosity};
use crate::tex::{tokenize, Kind, Token};

/// Format a LaTeX source file.
pub struct Formatter<'a> {
    cfg: &'a Config,
    file: String,
    /// Output lines.
    out: Vec<String>,
    /// Current indentation level.
    level: i32,
    /// Number of output lines written so far.
    out_num: usize,
    /// Number of input line being processed.
    in_num: usize,
    /// Index of first output line with negative indentation.
    first_negative: Option<usize>,
    /// Index of last output line with zero indentation.
    last_zero: Option<usize>,
}

/// Result of attempting to split a line for wrapping.
enum Split {
    /// Line cannot be split any further.
    None,
    /// Line was split into head and remainder.
    Parts(Vec<Token>, Vec<Token>, String),
}

impl<'a> Formatter<'a> {
    pub fn new(cfg: &'a Config, file: &str) -> Formatter<'a> {
        Formatter {
            cfg,
            file: file.to_string(),
            out: vec![],
            level: 0,
            out_num: 0,
            in_num: 0,
            first_negative: None,
            last_zero: None,
        }
    }

    fn log(&self, verbosity: Verbosity, msg: &str) {
        log::log(verbosity, self.cfg.verbosity, &self.file, msg);
    }

    fn line_msg(&self, verbosity: Verbosity, msg: &str, content: &str) {
        self.log(
            verbosity,
            &format!(
                "Line {} ({}). {} {}",
                self.out_num + 1,
                self.in_num,
                msg,
                content
            ),
        );
    }

    /// Compute indentation level of a line from its tokens.
    fn dedent(tokens: &[Token]) -> i32 {
        let mut depth = 0i32;
        let mut dedent = 0i32;
        for (i, tok) in tokens.iter().enumerate() {
            if i == 0 && tok.is_item() {
                dedent += 1;
            }
            for &p in &tok.parts {
                if p > 0 {
                    depth += p;
                } else if depth >= -p {
                    depth += p;
                } else {
                    dedent += -p - depth;
                    depth = 0;
                }
            }
        }
        dedent
    }

    /// Total indentation change of a list of tokens.
    fn delta(tokens: &[Token]) -> i32 {
        tokens.iter().map(|t| t.delta).sum()
    }

    /// Concatenate tokens into a string, keeping separators.
    fn content(tokens: &[Token]) -> String {
        let mut s = String::new();
        for t in tokens {
            s.push_str(&t.sep);
            s.push_str(&t.text);
        }
        s
    }

    /// Width of a string in characters.
    fn width(s: &str) -> usize {
        s.chars().count()
    }

    /// Indentation string for a given level.
    fn indent_str(&self, level: i32) -> String {
        let n = cmp::max(level, 0) as usize * self.cfg.tabsize;
        if self.cfg.tabchar.is_tab() {
            "\t".repeat(n)
        } else {
            " ".repeat(n)
        }
    }

    /// Width of indentation at a given level, used when wrapping.
    fn indent_width(&self, level: i32) -> usize {
        cmp::max(level, 0) as usize * self.cfg.tabsize
    }

    /// True if line needs to be wrapped.
    fn too_long(&self, level: i32, content: &str) -> bool {
        self.cfg.wrap && self.indent_width(level) + Self::width(content) > self.cfg.wraplen
    }

    /// Split tokens at characters after which lines may be wrapped.
    fn apply_wrap_chars(&self, tokens: &[Token]) -> Vec<Token> {
        if self.cfg.wrap_chars.is_empty() {
            return tokens.to_vec();
        }
        let mut out = vec![];
        for tok in tokens {
            let mut pieces = vec![];
            let mut cur = String::new();
            for c in tok.text.chars() {
                cur.push(c);
                if self.cfg.wrap_chars.contains(&c) {
                    pieces.push(cur);
                    cur = String::new();
                }
            }
            if !cur.is_empty() {
                pieces.push(cur);
            }
            if pieces.len() <= 1 {
                out.push(tok.clone());
                continue;
            }
            for (i, p) in pieces.iter().enumerate() {
                let mut t = tok.clone();
                t.text = p.clone();
                t.delta = 0;
                t.parts = vec![];
                t.kind = Kind::Text;
                t.split = false;
                if i > 0 {
                    t.sep = String::new();
                }
                out.push(t);
            }
        }
        out
    }

    /// Find position at which line should be broken, if any.
    /// Returns `Split::None` when the line cannot be split.
    fn find_split(&self, tokens: &[Token], level: i32) -> Split {
        let visual = level - Self::dedent(tokens);
        let indent = self.indent_width(visual);
        // Check whether remainder of tokens fits on a single line.
        if tokens.len() > 1 {
            let rest = Self::content(&tokens[1..]);
            if indent + Self::width(&rest) <= self.cfg.wraplen {
                return Split::Parts(tokens[..1].to_vec(), tokens[1..].to_vec(), rest);
            }
        }
        // Fill line with as many tokens as possible.
        let mut len = indent;
        let mut i = 0;
        while i < tokens.len() {
            let w = Self::width(&tokens[i].sep) + Self::width(&tokens[i].text);
            if len + w < self.cfg.wrapmin {
                len += w;
                i += 1;
            } else {
                break;
            }
        }
        if i == 0 {
            i = 1;
        }
        if i >= tokens.len() {
            return Split::None;
        }
        // Check whether remainder now fits on one line.
        let rest = Self::content(&tokens[i..]);
        if indent + Self::width(&rest) <= self.cfg.wraplen {
            return Split::Parts(tokens[..i].to_vec(), tokens[i..].to_vec(), rest);
        }
        Split::Parts(tokens[..i].to_vec(), tokens[i..].to_vec(), rest)
    }

    /// Process a line, appending output lines and returning new level.
    fn wrap_line(&mut self, tokens: &[Token], level: i32, content: &str, comment: bool) -> i32 {
        let tokens = self.apply_wrap_chars(tokens);
        let dedent = Self::dedent(&tokens);
        let visual = level - dedent;
        let actual = level + Self::delta(&tokens);
        let content = content.to_string();
        self.trace_indent(&content, actual, visual);
        if visual < 0 {
            self.line_msg(Verbosity::Warn, "Indent is negative", &content);
        }
        if !self.too_long(visual, &content) {
            self.push_line(visual, &content, actual);
            return actual;
        }
        self.log(
            Verbosity::Trace,
            &format!(
                "Line {} ({}). Wrapping long line. {}",
                self.out_num + 1,
                self.in_num,
                content
            ),
        );
        match self.find_split(&tokens, level) {
            Split::None => {
                self.line_msg(Verbosity::Warn, "Line cannot be wrapped", &content);
                self.push_line(visual, &content, actual);
            }
            Split::Parts(head, rest, rest_content) => {
                // Head content includes single separating space of next token.
                let mut head_content = Self::content(&head);
                if let Some(first) = rest.first() {
                    if let Some(c) = first.sep.chars().next() {
                        head_content.push(c);
                    }
                }
                let head_visual = level - Self::dedent(&head);
                if self.too_long(head_visual, &head_content) {
                    self.line_msg(Verbosity::Warn, "Line cannot be wrapped", &content);
