    fn dedent(tokens: &[Token]) -> i32 {
        let mut depth = 0i32;
        let mut dedent = 0i32;
        for (i, tok) in tokens.iter().enumerate() {
            if i == 0 && tok.is_item() {
                dedent += 1;
            }
            for &p in &tok.parts {
                if p > 0 {
                    depth += p;
                } else if depth >= -p {
                    depth += p;
                } else {
                    dedent += -p - depth;
                    depth = 0;
                }
            }
        }
        dedent
    }

    /// Total indentation change of a list of tokens.
    fn delta(tokens: &[Token]) -> i32 {
        tokens.iter().map(|t| t.delta).sum()
    }

