        let mut i = 0;
        while i < tokens.len() {
            let w = Self::width(&tokens[i].sep) + Self::width(&tokens[i].text);
            if len + w < self.cfg.wrapmin {
                len += w;
                i += 1;
            } else {
                break;
            }
        }
        if i == 0 {
            i = 1;
        }
        if i >= tokens.len() {
            return Split::None;
        }
        // Check whether remainder now fits on one line.
        let rest = Self::content(&tokens[i..]);
        if indent + Self::width(&rest) <= self.cfg.wraplen {
            return Split::Parts(tokens[..i].to_vec(), tokens[i..].to_vec(), rest);
        }
        Split::Parts(tokens[..i].to_vec(), tokens[i..].to_vec(), rest)
    }

