            Split::None => {
                self.line_msg(Verbosity::Warn, "Line cannot be wrapped", &content);
                self.push_line(visual, &content, actual);
            }
            Split::Parts(head, rest, rest_content) => {
                // Head content includes single separating space of next token.
                let mut head_content = Self::content(&head);
                if let Some(first) = rest.first() {
                    if let Some(c) = first.sep.chars().next() {
