    /// Number of input line being processed.
    in_num: usize,
    /// Index of first output line with negative indentation.
    first_negative: Option<usize>,
    /// Index of last output line with zero indentation.
    last_zero: Option<usize>,
}

impl<'a> Formatter<'a> {
    pub fn new(cfg: &'a Config, file: &str) -> Formatter<'a> {
        Formatter {
            cfg,
            file: file.to_string(),
            out: vec![],
            level: 0,
            out_num: 0,
            in_num: 0,
            first_negative: None,
            last_zero: None,
        }
    }

    fn log(&self, verbosity: Verbosity, msg: &str) {
        log::log(verbosity, self.cfg.verbosity, &self.file, msg);
    }

    fn line_msg(&self, verbosity: Verbosity, msg: &str, content: &str) {
        self.log(
            verbosity,
            &format!(
                "Line {} ({}). {} {}",
                self.out_num + 1,
                self.in_num,
                msg,
                content
            ),
        );
    }

    /// Compute indentation level of a line from its tokens.
    fn dedent(tokens: &[Token]) -> i32 {
        let mut depth = 0i32;
        let mut dedent = 0i32;
        for (i, tok) in tokens.iter().enumerate() {
            if i == 0 && tok.is_item() {
                dedent += 1;
            }
            for &p in &tok.parts {
                if p > 0 {
                    depth += p;
                } else if depth >= -p {
                    depth += p;
                } else {
                    dedent += -p - depth;
                    depth = 0;
                }
            }
        }
        dedent
    }

    /// Total indentation change of a list of tokens.
    fn delta(tokens: &[Token]) -> i32 {
        tokens.iter().map(|t| t.delta).sum()
    }

    /// Concatenate tokens into a string, keeping separators.
    fn content(tokens: &[Token]) -> String {
        let mut s = String::new();
        for t in tokens {
            s.push_str(&t.sep);
            s.push_str(&t.text);
        }
        s
    }

