    fn process_line(&mut self, raw: &str) {
        let tokens = tokenize(raw, self.cfg);
        let content = Self::content(&tokens);
        self.in_num += 1;
        let level = self.level;
        self.wrap_line(&tokens, level, &content);
        self.level = self.level;
    }

