//! `tex-fmt` is a fast LaTeX formatter.
mod args;
mod config;
mod format;
mod log;
mod tex;

use std::io::Read;
use std::path::Path;

use clap_complete::{generate as generate_completion, Shell};
use config::{Config, TabChar};
use log::Verbosity;

fn main() {
    let matches = args::build_cli().get_matches();

    let shell = matches.get_one::<String>("completion").cloned();
    if let Some(shell) = shell {
        let shell = Shell::from_str_name(&shell).unwrap();
        let mut cmd = args::build_cli();
        generate_completion(shell, &mut cmd, "tex-fmt", &mut std::io::stdout());
        std::process::exit(0);
    }
    if matches.get_flag("man") {
        print_man();
        std::process::exit(0);
    }

    // Build configuration.
    let mut cfg = Config::default();
    let mut had_wrapmin = false;
    let config_path = matches.get_one::<String>("config").cloned();
    let noconfig = matches.get_flag("noconfig");
    if !noconfig {
        if let Some(path) = &config_path {
            cfg.read_toml(path);
            cfg.config = Some(path.clone());
        } else if let Some(path) = config::find_config() {
            let p = path.to_string_lossy().to_string();
            cfg.read_toml(&p);
            cfg.config = Some(p);
        }
    }
    // Apply command line arguments.
    let wraplen: usize = matches.get_one::<String>("wraplen").unwrap().parse().unwrap();
    let tabsize: usize = matches.get_one::<String>("tabsize").unwrap().parse().unwrap();
    let wraplen_given = matches.get_one::<String>("wraplen").is_some();
    if wraplen_given {
        cfg.wraplen = wraplen;
