/// Expand tabs and trim trailing whitespace of a raw line.
fn clean_line(raw: &str, tabsize: usize) -> String {
    crate::tex::expand_tabs(raw, tabsize).trim_end_matches(' ').to_string()
}

/// Kind of ignore directive found in a line.
enum Directive {
    Off,
    On,
    Skip,
}

/// Look for a `tex-fmt` ignore directive in a line.
fn directive(tokens: &[Token], cfg: &Config) -> Option<Directive> {
    for tok in tokens {
        if !tok.comment {
            continue;
        }
        if tok.text == "% tex-fmt: off" {
            return Some(Directive::Off);
        }
        if tok.text == "% tex-fmt: on" {
            return Some(Directive::On);
        }
        if tok.text == "% tex-fmt: skip" {
            return Some(Directive::Skip);
        }
        return None;
    }
    None
}

/// Find verbatim environment starting in a line.
fn verbatim_begin(tokens: &[Token], cfg: &Config) -> Option<String> {
    for tok in tokens {
        if let Kind::Begin(env) = &tok.kind {
            if crate::tex::is_verbatim(env, cfg) {
                return Some(env.clone());
            }
        }
    }
    None
}

/// True if line contains end of given environment.
fn verbatim_end(tokens: &[Token], env: &str) -> bool {
    tokens.iter().any(|t| matches!(&t.kind, Kind::End(e) if e == env))
}

/// Format the content of a file.
pub fn format(content: &str, cfg: &Config, file: &str) -> String {
    let mut f = Formatter::new(cfg, file);
    let mut in_verbatim: Option<String> = None;
    let mut ignore = false;
    for raw in content.split('\\n') {
        f.in_num += 1;
        let raw = raw.strip_suffix('\\r').unwrap_or(raw);
        if let Some(env) = in_verbatim.clone() {
            let line = clean_line(raw, cfg.tabsize);
            let tokens = tokenize(&line, cfg);
            f.out.push(line);
            f.out_num += 1;
            if verbatim_end(&tokens, &env) {
                in_verbatim = None;
            }
            continue;
        }
        let tokens = tokenize(raw, cfg);
        match directive(&tokens, cfg) {
            Some(Directive::Off) => {
                if ignore {
                    f.line_msg(
