//! Generation of a man page from the command line interface.
use roff::{roman, italic, line_break, Inline, Roff};

use crate::args;

/// Render man page as string.
pub fn render_man() -> String {
    let cmd = args::build_cli();
    let name = args::NAME.to_string();
    let version = args::VERSION.to_string();
    let about = args::ABOUT.to_string();
    let author = args::AUTHOR.to_string();

    let mut roff = Roff::new();
    // .TH line
    roff.control("TH", [
        &escape(&name),
        "1",
        "",
        &format!("\\\"{} {}\\\"", name, version),
        "",
    ]);
    // NAME
    roff.control("SH", ["NAME"]);
    roff.text([roman(&format!("{} \\- {}", escape(&name), about))]);
    // SYNOPSIS
    roff.control("SH", ["SYNOPSIS"]);
    let mut synopsis: Vec<Inline> = vec![roman(&format!("\\fB{}\\fR", escape(&name)))];
    for opt in cmd.get_arguments() {
        if !opt.is_positional() {
            let mut parts = vec![];
            match (opt.get_short(), opt.get_long()) {
                (Some(s), Some(l)) => {
                    parts.push(roman("\\fB\\-"));
                    parts.push(roman(&s.to_string()));
                    parts.push(roman("\\fR|\\fB\\-\\-"));
                    parts.push(roman(&escape(l)));
                    parts.push(roman("\\fR"));
                }
                (Some(s), None) => {
                    parts.push(roman("\\fB\\-"));
                    parts.push(roman(&s.to_string()));
                    parts.push(roman("\\fR"));
                }
                (None, Some(l)) => {
                    parts.push(roman("\\fB\\-\\-"));
                    parts.push(roman(&escape(l)));
                    parts.push(roman("\\fR"));
                }
                _ => {}
            }
            synopsis.push(roman("["));
            synopsis.extend(parts);
            synopsis.push(roman("] "));
        }
    }
    for pos in cmd.get_arguments().filter(|a| a.is_positional()) {
        let value = match pos.get_value_names() {
            Some(v) => v.join(" "),
            None => pos.get_id().to_string(),
        };
        synopsis.push(roman("["));
        synopsis.push(italic(value));
        synopsis.push(roman("] "));
    }
    roff.text(synopsis);
    // DESCRIPTION
    roff.control("SH", ["DESCRIPTION"]);
    roff.text([roman(about)]);
    // OPTIONS
    roff.control("SH", ["OPTIONS"]);
    for opt in cmd.get_arguments() {
        if opt.is_positional() {
            continue;
        }
        let mut header: Vec<Inline> = vec![];
        match (opt.get_short(), opt.get_long()) {
            (Some(s), Some(l)) => {
                header.push(roman(&format!("\\fB\\-{}\\fR, \\fB\\-\\-{}\\fR", s, escape(l))));
            }
            (Some(s), None) => {
                header.push(roman(&format!("\\fB\\-{}\\fR", s)));
            }
            (None, Some(l)) => {
                header.push(roman(&format!("\\fB\\-\\-{}\\fR", escape(l))));
            }
            _ => {}
        }
        if opt.get_num_args().map(|r| r.takes_values()).unwrap_or(false) {
