//! Generation of a man page from the command line interface.
use roff::{bold, italic, line_break, roman, Inline, Roff};

use crate::args;

/// Render man page as string.
pub fn render_man() -> String {
    let mut cmd = args::build_cli();
    cmd.build();
    let name = args::NAME.to_string();
    let version = args::VERSION.to_string();
    let about = args::ABOUT.to_string();
    let author = args::AUTHOR.to_string();

    let mut roff = Roff::new();
    roff.control("TH", [&name, "1", "", &format!("{} {}", name, version), ""]);
    // NAME
    roff.control("SH", ["NAME"]);
    roff.text([roman(format!("{} \\- {}", name, about))]);
    // SYNOPSIS
    roff.control("SH", ["SYNOPSIS"]);
    let mut synopsis: Vec<Inline> = vec![bold(name.clone())];
    for opt in cmd.get_arguments() {
        if !opt.is_positional() {
            let mut parts: Vec<Inline> = vec![];
            match (opt.get_short(), opt.get_long()) {
                (Some(s), Some(l)) => {
                    parts.push(bold(format!("-{}", s)));
                    parts.push(roman("|"));
                    parts.push(bold(format!("--{}", l)));
                }
                (Some(s), None) => {
                    parts.push(bold(format!("-{}", s)));
                }
                (None, Some(l)) => {
                    parts.push(bold(format!("--{}", l)));
                }
                _ => {}
            }
            synopsis.push(roman("["));
            synopsis.extend(parts);
            synopsis.push(roman("] "));
        }
    }
    for pos in cmd.get_arguments().filter(|a| a.is_positional()) {
        let value = match pos.get_value_names() {
            Some(v) => v.join(" "),
            None => pos.get_id().to_string(),
        };
        synopsis.push(roman("["));
        synopsis.push(italic(value));
        synopsis.push(roman("] "));
    }
    roff.text(synopsis);
    // DESCRIPTION
    roff.control("SH", ["DESCRIPTION"]);
    roff.text([roman(about.clone())]);
    // OPTIONS
    roff.control("SH", ["OPTIONS"]);
    for opt in cmd.get_arguments() {
        if opt.is_positional() {
            continue;
        }
        let mut header: Vec<Inline> = vec![];
        match (opt.get_short(), opt.get_long()) {
            (Some(s), Some(l)) => {
                header.push(bold(format!("-{}", s)));
                header.push(roman(", "));
                header.push(bold(format!("--{}", l)));
            }
            (Some(s), None) => {
                header.push(bold(format!("-{}", s)));
            }
            (None, Some(l)) => {
                header.push(bold(format!("--{}", l)));
            }
            _ => {}
        }
        if opt.get_num_args().map(|r| r.takes_values()).unwrap_or(false) {
            if let Some(names) = opt.get_value_names() {
                header.push(roman(" "));
                header.push(italic(format!("<{}>", names[0])));
            }
        }
        roff.control("TP", []);
        roff.text(header);
        let mut body: Vec<Inline> = vec![];
        if let Some(help) = opt.get_help() {
            body.push(roman(help.to_string()));
        }
        if !opt.get_possible_values().is_empty() {
            let values: Vec<String> = opt
                .get_possible_values()
                .iter()
                .filter(|pv| !pv.is_hide_set())
                .map(|pv| pv.get_name().to_string())
                .collect();
            body.push(line_break());
            body.push(line_break());
            body.push(roman("["));
            body.push(italic("possible values: "));
            body.push(roman(values.join(", ")));
            body.push(roman("]"));
        }
        roff.text(body);
    }
    for pos in cmd.get_arguments().filter(|a| a.is_positional()) {
        let value = match pos.get_value_names() {
            Some(v) => v.join(" "),
            None => pos.get_id().to_string(),
        };
        let header: Vec<Inline> = vec![roman("["), italic(value), roman("]")];
        roff.control("TP", []);
        roff.text(header);
        if let Some(help) = pos.get_help() {
            roff.text([roman(help.to_string())]);
        }
    }
    // VERSION
    roff.control("SH", ["VERSION"]);
    roff.text([roman(format!("v{}", version))]);
    // AUTHORS
    roff.control("SH", ["AUTHORS"]);
    roff.text([roman(author)]);

    roff.render()
}
