import subprocess, os, sys, glob
REF='/workspace/executable'
MINE='/tmp/impl/target/release/tex-fmt'
def run(binary, args, cwd=None, stdin=None):
    r = subprocess.run([binary]+args, capture_output=True, text=True, cwd=cwd, input=stdin)
    return (r.stdout, r.stderr, r.returncode)
def cmp_file(path, args, label='', show=True):
    a = run(REF, args)
    b = run(MINE, args)
    if a != b:
        if show:
            print(f"=== DIFF {path} {args} {label}")
            names=['stdout','stderr','rc']
            for i in range(3):
                if a[i]!=b[i]:
                    print(f"  -- {names[i]}")
                    if i<2:
                        al=a[i].split('\n'); bl=b[i].split('\n')
                        for j,(x,y) in enumerate(zip(al,bl)):
                            if x!=y: print(f"   L{j}: ref {x[:150]!r}"); print(f"        mine {y[:150]!r}")
                        if len(al)!=len(bl): print(f"   lens {len(al)} vs {len(bl)}")
                    else: print(f"   ref {a[i]} mine {b[i]}")
        return False
    return True
