new = '''fn scan(chars: &[char], start: usize, cfg: &Config, comment: bool) -> (usize, Token) {
    let mut pos = start;
    if !comment && chars[start] == '%' {
        // Comment token: '%' and directly following characters.
        let mut end = start + 1;
        while end < chars.len() && chars[end] != ' ' {
            end += 1;
        }
        let mut tok = Token::new(chars[start..end].iter().collect(), String::new());
        tok.comment = true;
        return (end, tok);
    }
    let mut delta = 0i32;
    let mut parts: Vec<i32> = vec![];
    let mut kind = Kind::Text;
    let mut item = false;
    while pos < chars.len() {
        let c = chars[pos];
        if !comment && c == '%' {
            break;
        }
        if c == ' ' {
            break;
        }
        if c == '\\\\' && pos + 1 < chars.len() {
            if let Some(name) = special_name(chars, pos) {
                let cmd_len = name.chars().count() + 1;
                match name {
                    "begin" | "end" => {
                        let brace = pos + cmd_len;
                        let (env, after) = parse_env(chars, brace);
                        if let Some(env) = env {
                            let d = env_delta(&env, cfg);
                            if name == "begin" {
                                delta += d;
                                kind = Kind::Begin(env);
                            } else {
                                delta -= d;
                                parts.push(-d);
                                kind = Kind::End(env);
                            }
                            pos = after;
                        } else {
                            if name == "begin" {
                                delta += 1;
                            } else {
                                delta -= 1;
                                parts.push(-1);
                            }
                            pos = brace;
                        }
                    }
                    _ => {
                        // item
                        item = true;
                        pos += cmd_len;
                    }
                }
                continue;
            }
            let next = chars[pos + 1];
            match next {
                '[' => {
                    delta += 1;
                    parts.push(1);
                    pos += 2;
                    continue;
                }
                ']' => {
                    delta -= 1;
                    parts.push(-1);
                    pos += 2;
                    continue;
                }
                '\\' => {
                    pos += 2;
                    continue;
                }
                _ if next.is_alphabetic() => {
                    let mut j = pos + 1;
                    while j < chars.len() && chars[j].is_alphabetic() {
                        j += 1;
                    }
                    pos = j;
                    continue;
                }
                _ => {
                    pos += 2;
                    continue;
                }
            }
        }
        match c {
            '{' => {
                delta += 1;
                parts.push(1);
                pos += 1;
            }
            '}' => {
                delta -= 1;
                parts.push(-1);
                pos += 1;
            }
            _ => pos += 1,
        }
    }
    if item {
        kind = Kind::Item;
    }
    let text: String = chars[start..pos].iter().collect();
    let mut tok = Token::new(text, String::new());
    tok.delta = delta;
    tok.parts = parts;
    tok.kind = kind;
    (pos, tok)
